/**
 * @name Command injection via .env file parsing
 * @description Detects command injection where untrusted .env file content flows to shell command execution
 * @kind path-problem
 * @problem.severity error
 * @id python/command-injection-dotenv
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module DotenvCommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Sources: file reading operations that could read .env files
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      source = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pathlib").getMember("Path").getACall() and
      source = call.getArg(0)
    ) or
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Sinks: shell command execution
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember(["call", "run", "Popen"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module DotenvCommandInjectionFlow = TaintTracking::Global<DotenvCommandInjectionConfig>;
import DotenvCommandInjectionFlow::PathGraph

from DotenvCommandInjectionFlow::PathNode source, DotenvCommandInjectionFlow::PathNode sink
where DotenvCommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "file path"
